import * as Effect from "effect/Effect"

// Percent-encoding leaves only ASCII, which `btoa` encodes byte for byte.
export const basicCredentials = (
  clientId: string,
  secret: string | undefined,
  authentication: "basic" | "post"
): Effect.Effect<string | undefined> => {
  const basic = secret === undefined || authentication !== "basic"
    ? undefined
    : btoa(`${encodeURIComponent(clientId)}:${encodeURIComponent(secret)}`)
  return Effect.succeed(basic)
}

export const githubBasic = (clientId: string, secret: string): Effect.Effect<string> =>
  Effect.succeed(btoa([clientId, secret].map(encodeURIComponent).join(":")))
